INSERT INTO ADMIN_BOARD (

    SELECT
        'ABNO'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(BOARD_NO), LENGTH('ABNO' ) + 1)), 0) + 1, 6, '0')
    FROM ADMIN_BOARD

	BOARD_NO
	, USER_ID
	, BOARD_TYPE_CODE
	, BOARD_TITLE
	, BOARD_WRITE_DATE
	, BOARD_CONTENT
	, BOARD_POST_HIT
	, BOARD_STATUS
) VALUES (
	#{boardNo}
	, #{userId}
	, #{boardTypeCode}
	, #{boardTitle}
	, sysdate
	, #{boardContent}
	, #{boardPostHit}
	, #{boardStatus}
)

