UPDATE ADMIN_BOARD 
SET 
	USER_ID = #{userId}
	, BOARD_TYPE_CODE = #{boardTypeCode}
	, BOARD_TITLE = #{boardTitle}
	, BOARD_CONTENT = #{boardContent}
	, BOARD_DELETE_DATE = #{boardDeleteDate}
	, BOARD_POST_HIT = #{boardPostHit}
	, BOARD_STATUS = #{boardStatus} 
WHERE 
	BOARD_NO = #{boardNo}
